//! 🧪️ Original sparse diff text receives exact UTF8 bytes and keeps partial output through denial and cancellation.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64}}
#[test]
fn original_paged_text_matches_independent_serde_string_without_payload_proxy(){let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){for cut in [0,1,3,10000]{let g=grant();let raw:DrawingNativeText=case.as_str().unwrap().into();let mut source=RetainedCloneSource::admit_owned(raw,(),g).unwrap_or_else(|_|panic!("original sparse text source")).0;let mut owner=DrawingOriginalText::default();for _ in 0..cut{let d=owner.demand(source.borrow(),g.maximum_copy_bytes).unwrap();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=0,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=0,3 if d.release_bytes>0=>denied.maximum_release_bytes=0,4 if d.depth>0=>denied.maximum_depth=0,_=>continue}let(step,b,r)=semio_framework_trace_memory_testing::observe_backing(||owner.advance(source.borrow(),g.maximum_copy_bytes,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((b,r),(0,0));assert_eq!(owner.demand(source.borrow(),g.maximum_copy_bytes).unwrap(),d);}let(step,b,r)=semio_framework_trace_memory_testing::observe_backing(||owner.advance(source.borrow(),g.maximum_copy_bytes,g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!((b,r),(p.retained_capacity_bytes,p.released_bytes));if owner.ready(){break}}if cut==10000{assert!(owner.ready())}if owner.ready(){let(output,p)=owner.take(g).unwrap();assert!(p.fits(g));let output=output.unwrap();assert_eq!(serde_json::to_value(&output).unwrap(),*case);let mut close=semio_framework_value::retirement::controlled::ControlledRetirement::new(output).unwrap_or_else(|_|panic!("original String output close"));while !close.terminal_is_empty(){close.step(g).unwrap();}}owner.begin_close();for _ in 0..10000{if owner.terminal_is_empty(){break}let(step,b,r)=semio_framework_trace_memory_testing::observe_backing(||owner.close_step(g).unwrap());let p=step.progress();assert_eq!((b,r),(p.retained_capacity_bytes,p.released_bytes));}assert!(owner.terminal_is_empty());while !source.terminal_is_empty(){source.close_step(g).unwrap();}}}}
